-- Run this in Supabase SQL Editor. Safe to run anytime —
-- creates a NEW table, does not touch your existing registrations
-- or their data.

create table if not exists allowed_students (
  reg_number text primary key
);

alter table allowed_students enable row level security;

-- The registration form needs to check this list before letting
-- someone submit, so it needs to be readable by anon.
-- Nobody can INSERT/UPDATE/DELETE here via the website — only you,
-- pasting SQL directly into the SQL Editor (that runs with full
-- admin rights and ignores RLS).
create policy "Anyone can check the allowed list"
on allowed_students
for select
to anon
using (true);

-- Your approved list (275 reg numbers)
on conflict (reg_number) do nothing;
